#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) {
    malloc_reset();
}

void unit_test_push_realloc_failure(void) {
    Vector* vec = NULL;
    int val = 42;
    int result;

    vec = (Vector*)malloc(sizeof(Vector));
    TEST_ASSERT_NOT_NULL(vec);

    vec->contents = (int*)malloc(sizeof(int) * 5);
    TEST_ASSERT_NOT_NULL(vec->contents);
    vec->len = 5;

    malloc_fail_after(2);

    result = push(vec, val);
    TEST_ASSERT_EQUAL_INT(-1, result);

    // Clean up allocations made before push failure
    free(vec->contents);
    free(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_push_realloc_failure);
    return UNITY_END();
}

